'use client';

import type { Variants } from 'motion/react';
import { motion, useAnimation } from 'motion/react';
import type { HTMLAttributes } from 'react';
import { forwardRef } from 'react';
import { useIconAnimation } from '@/lib/use-icon-animation';
import { cn } from '@/lib/utils';

export interface SnowIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface SnowIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

// The flake winds up against the turn, then twirls one full turn as a single
// rigid crystal (every arm stays joined at the center), overshoots, and
// settles back. A full turn ends exactly on the rest pose.
const snowVariants: Variants = {
  normal: { transform: 'rotate(0deg) scale(1)' },
  animate: {
    transform: [
      'rotate(0deg) scale(1)',
      'rotate(-20deg) scale(0.9)',
      'rotate(376deg) scale(1.08)',
      'rotate(355deg) scale(0.98)',
      'rotate(360deg) scale(1)',
    ],
    transition: {
      duration: 1.2,
      ease: ['easeInOut', [0.5, 0, 0.2, 1], 'easeInOut', 'easeOut'],
      times: [0, 0.2, 0.64, 0.84, 1],
    },
  },
};

const SnowIcon = forwardRef<SnowIconHandle, SnowIconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
    const controls = useAnimation();
    const { handleMouseEnter, handleMouseLeave } = useIconAnimation({
      controls,
      loops: false,
      onMouseEnter,
      onMouseLeave,
      ref,
    });

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <motion.svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
          variants={snowVariants}
          animate={controls}
          initial="normal"
          style={{ transformOrigin: '50% 50%' }}
        >
          <path
            d="M21 14.25L20.1689 13.591C19.223 12.841 18.75 12.466 18.75 12C18.75 11.534 19.223 11.159 20.1689 10.409L21 9.75M3 9.75L3.83115 10.409C4.77705 11.159 5.25 11.534 5.25 12C5.25 12.466 4.77705 12.841 3.83115 13.591L3 14.25"
